class Main {
    public static void main(String[] args) {
        // 쿠키 수와 한 상자에 담는 개수예요.
        int cookies = 17;
        int size = 5;
        // 꽉 채운 상자 수는 몫으로 구해요.
        int boxes = cookies / size;
        System.out.println(boxes);
        // 상자에 못 담고 남은 쿠키 수를 구할 자리예요.
        int left = cookies / size;
        System.out.println(left);
    }
